BEGIN;
CREATE TABLE IF NOT EXISTS max_kb_model_provider (
 provider varchar(128) PRIMARY KEY, name varchar(200) NOT NULL, icon text NOT NULL DEFAULT '',
 api_base text NOT NULL DEFAULT '', protocol varchar(40) NOT NULL DEFAULT 'OPENAI_COMPATIBLE',
 model_types jsonb NOT NULL, credential_form jsonb NOT NULL, params_form jsonb NOT NULL,
 enabled boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0,
 updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS max_kb_model_catalog (
 provider varchar(128) REFERENCES max_kb_model_provider(provider), model_type varchar(30) NOT NULL,
 model_id varchar(256) NOT NULL, description text, source text NOT NULL DEFAULT 'seed',
 enabled boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(provider,model_type,model_id));
ALTER TABLE max_kb_model ADD COLUMN IF NOT EXISTS model_params_form jsonb NOT NULL DEFAULT '[]';
