UPDATE max_kb_model SET provider='model_gitee_provider' WHERE id IN (1001,1002) AND provider='model_openai_provider' AND credential::jsonb='{}'::jsonb;
INSERT INTO max_kb_model_catalog(provider,model_type,model_id,description,source)
 SELECT DISTINCT provider,model_type,model_name,model_name,'installed'
 FROM max_kb_model m WHERE EXISTS(SELECT 1 FROM max_kb_model_provider p WHERE p.provider=m.provider)
 ON CONFLICT DO NOTHING;
